#!/usr/bin/env python3
"""
FULL deterministic label window: all 124 id-only + 76 named = 200 items
(path A: use every row the ordered LIMIT-200 window affords, for power).
The 18+12 subset was underpowered on the deterministic window (Qwen3-30B
implicit->explicit 7/18->10/18, McNemar p=0.45), so we score the whole window.

Data pulled from rdfportal.org/ebi (ORDER BY ?chemblId LIMIT 200), embedded
verbatim as endpoint GROUP_CONCAT output. The endpoint reported COUNT n=124 and
n=76; parsing these strings must reproduce those counts (a transcription
checksum: a dropped/added '@@' changes the count).
"""
import re, yaml

ID_ONLY_RAW = "CHEMBL10276@@CHEMBL104728@@CHEMBL104732@@CHEMBL105739@@CHEMBL1078244@@CHEMBL1080147@@CHEMBL1080510@@CHEMBL1080687@@CHEMBL1080744@@CHEMBL1080861@@CHEMBL1080897@@CHEMBL1080915@@CHEMBL1080918@@CHEMBL1081075@@CHEMBL1081635@@CHEMBL1081842@@CHEMBL1082160@@CHEMBL1084441@@CHEMBL1085065@@CHEMBL1086872@@CHEMBL1087646@@CHEMBL1088018@@CHEMBL1091028@@CHEMBL1091971@@CHEMBL1093246@@CHEMBL1093507@@CHEMBL1094843@@CHEMBL1095276@@CHEMBL1096339@@CHEMBL1096706@@CHEMBL1099177@@CHEMBL111951@@CHEMBL112060@@CHEMBL112597@@CHEMBL113545@@CHEMBL114059@@CHEMBL114249@@CHEMBL114408@@CHEMBL114544@@CHEMBL1162110@@CHEMBL1162293@@CHEMBL1164527@@CHEMBL1165202@@CHEMBL116569@@CHEMBL1169388@@CHEMBL1169929@@CHEMBL1170681@@CHEMBL1170871@@CHEMBL1170891@@CHEMBL1172995@@CHEMBL1173141@@CHEMBL1173146@@CHEMBL1173570@@CHEMBL1173823@@CHEMBL1178@@CHEMBL1179189@@CHEMBL117966@@CHEMBL118009@@CHEMBL118109@@CHEMBL118175@@CHEMBL1183559@@CHEMBL1185172@@CHEMBL1186087@@CHEMBL11875@@CHEMBL1190095@@CHEMBL1195425@@CHEMBL1197686@@CHEMBL119769@@CHEMBL1197859@@CHEMBL1197976@@CHEMBL1198132@@CHEMBL1198369@@CHEMBL119841@@CHEMBL1209196@@CHEMBL1213096@@CHEMBL1213347@@CHEMBL1213640@@CHEMBL1213769@@CHEMBL1213834@@CHEMBL1213905@@CHEMBL1213966@@CHEMBL1214345@@CHEMBL1214407@@CHEMBL1214410@@CHEMBL1214519@@CHEMBL1214525@@CHEMBL1215547@@CHEMBL1221601@@CHEMBL1221925@@CHEMBL1222317@@CHEMBL1222382@@CHEMBL1222385@@CHEMBL1222386@@CHEMBL1223140@@CHEMBL122355@@CHEMBL122701@@CHEMBL1231450@@CHEMBL1232243@@CHEMBL12329@@CHEMBL1234720@@CHEMBL1235116@@CHEMBL1236104@@CHEMBL124006@@CHEMBL1240755@@CHEMBL1241268@@CHEMBL1241371@@CHEMBL1241420@@CHEMBL1241453@@CHEMBL1241671@@CHEMBL1242180@@CHEMBL1253382@@CHEMBL1254832@@CHEMBL1255659@@CHEMBL1255755@@CHEMBL1255867@@CHEMBL1256024@@CHEMBL1256291@@CHEMBL1256364@@CHEMBL1256390@@CHEMBL1256697@@CHEMBL1257056@@CHEMBL1257130@@CHEMBL125812@@CHEMBL126804"

NAMED_RAW = "CHEMBL100473\tU-0126@@CHEMBL101\tPHENYLBUTAZONE@@CHEMBL101326\tFIPRONIL@@CHEMBL1014\tCANDESARTAN CILEXETIL@@CHEMBL1018\tDIENESTROL@@CHEMBL102714\tSB-216763@@CHEMBL10284\tSB-222200@@CHEMBL104\tCLOTRIMAZOLE@@CHEMBL1042\tCHOLECALCIFEROL@@CHEMBL104255\tFLAVOKAWAIN B@@CHEMBL105496\t4-METHOXY CHALCONE@@CHEMBL105712\tPHENACYL CHLORIDE@@CHEMBL107\tCOLCHICINE@@CHEMBL1070\tNABUMETONE@@CHEMBL1076347\tTRICLOCARBAN@@CHEMBL1078441\tR-(+)-MARMIN@@CHEMBL108\tCARBAMAZEPINE@@CHEMBL1082607\tSALMETEROL XINAFOATE@@CHEMBL1083993\tAMIODARONE HYDROCHLORIDE@@CHEMBL1088184\tDIBUTYLDICHLOROSTANNANE@@CHEMBL1088186\tTRIBUTYLCHLOROSTANNANE@@CHEMBL108829\t2-PHENYLPHENOL@@CHEMBL1098658\tYANGONIN@@CHEMBL1103\tFURAZOLIDONE@@CHEMBL1113\tAMOXAPINE@@CHEMBL1116\tRALOXIFENE HYDROCHLORIDE@@CHEMBL111743\tSTROPHANTHIDIN@@CHEMBL114957\tTOLUIC ACID@@CHEMBL1153\tDIGOXIGENIN@@CHEMBL1165553\tBROMODIOLONE@@CHEMBL117\tCHRYSIN@@CHEMBL1173475\tQUERCETIN DIHYDRATE@@CHEMBL117447\tPHENYL ISATIN@@CHEMBL1180\tO-DEMETHYLATED ADAPALENE@@CHEMBL1189\tDIETHYLAMINE@@CHEMBL1191361\tHYDROXYAMINE@@CHEMBL1192517\tBIFEMELANE@@CHEMBL1200326\tNICARDIPINE HYDROCHLORIDE@@CHEMBL1200339\tPHENYLEPHRINE HYDROCHLORIDE@@CHEMBL1200348\tSULCONAZOLE NITRATE@@CHEMBL1200471\tPYRITHIONE ZINC@@CHEMBL1200559\tLACTIC ACID@@CHEMBL1200585\tOXYMETHOLONE@@CHEMBL1200596\tCHLOROXINE@@CHEMBL1200627\tPROPIOLACTONE@@CHEMBL1200710\tCLOMIPRAMINE HYDROCHLORIDE@@CHEMBL1200756\tPYRIDOXINE HYDROCHLORIDE@@CHEMBL1200787\tPHENOXYBENZAMINE HYDROCHLORIDE@@CHEMBL1200868\tPHENYL AMINOSALICYLATE@@CHEMBL1200895\tPHENELZINE SULFATE@@CHEMBL1200916\tTHIORIDAZINE HYDROCHLORIDE@@CHEMBL1200964\tAMITRIPTYLINE HYDROCHLORIDE@@CHEMBL1200970\tETHOPROPAZINE HYDROCHLORIDE@@CHEMBL1201001\tMECHLORETHAMINE HYDROCHLORIDE@@CHEMBL1201049\tECONAZOLE NITRATE@@CHEMBL1201102\tTRIFLUPROMAZINE HYDROCHLORIDE@@CHEMBL1201103\tMETHOXAMINE HYDROCHLORIDE@@CHEMBL1201154\tPROCHLORPERAZINE EDISYLATE@@CHEMBL120563\tTHIRAM@@CHEMBL1208903\tISOGINKGETIN@@CHEMBL121663\tDEQUALINIUM CHLORIDE@@CHEMBL1224528\tDIHYDROXIDINE@@CHEMBL1228\tOXYPHENBUTAZONE ANHYDROUS@@CHEMBL1229846\tPHENOXYETHANOL@@CHEMBL123\tELLIPTECINE@@CHEMBL1231101\tACIVICIN@@CHEMBL1232792\tFENAMIDONE@@CHEMBL123292\tCYCLOHEXIMIDE@@CHEMBL1234557\tPENTADECANE@@CHEMBL1235482\tGLUTARAL@@CHEMBL1237135\tMAPROTILINE HYDROCHLORIDE@@CHEMBL1256028\tFIDUXOSIN HYDROCHLORIDE@@CHEMBL1256180\t5-(N-METHYL-N-ISOBUTYL)AMILORIDE@@CHEMBL1256709\tKETANSERIN TARTRATE@@CHEMBL1256841\tNIALAMIDE@@CHEMBL126077\tINDIRUBIN-3-MONOXIME"

ID_ONLY = ID_ONLY_RAW.split("@@")
NAMED = [row.split("\t") for row in NAMED_RAW.split("@@")]

assert len(ID_ONLY) == 124, f"id_only count {len(ID_ONLY)} != 124 (transcription!)"
assert len(NAMED) == 76, f"named count {len(NAMED)} != 76 (transcription!)"
assert all(re.fullmatch(r"CHEMBL\d+", c) for c in ID_ONLY)
assert all(len(r) == 2 and re.fullmatch(r"CHEMBL\d+", r[0]) and r[1] for r in NAMED)

QUERY = """PREFIX cco: <http://rdf.ebi.ac.uk/terms/chembl#>
      PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
      SELECT DISTINCT ?molecule ?moleculeLabel ?chemblId
      FROM <http://rdf.ebi.ac.uk/dataset/chembl>
      WHERE {
        VALUES ?target { <http://rdf.ebi.ac.uk/resource/chembl/target/CHEMBL4096> }
        ?activity a cco:Activity ;
                  cco:hasMolecule ?molecule ;
                  cco:hasAssay/cco:hasTarget ?target .
        ?molecule rdfs:label ?moleculeLabel ; cco:chemblId ?chemblId .
      } ORDER BY ?chemblId LIMIT 200"""
ABSTAIN = (r"(?i)(cannot (definitively|determine|tell)|impossible to "
           r"(tell|determine)|unable to (determine|tell)|no way to know)")


def name_regex(name):
    return r"(?i)\b" + r"\s+".join(re.escape(t) for t in name.split()) + r"\b"


def prompt(cid):
    return (
        'Call run_sparql with database="chembl" and execute EXACTLY the following '
        "query, without modifying it:\n\n" + QUERY + "\n\n"
        f"From the returned rows, find molecule {cid}. Report that molecule's real "
        "compound name. If it has no compound name, answer exactly NONE. Answer "
        "with the name or with NONE, nothing else.")


tasks = []
for cid in ID_ONLY:
    tasks.append({"id": f"t_labF_{cid}", "prompt": prompt(cid),
                  "answer_regex": r"(?i)\bNONE\b",
                  "trap": {"wrong_if_regex": f"(?i){cid}(?![0-9])"},
                  "abstain_regex": ABSTAIN})
for cid, nm in NAMED:
    tasks.append({"id": f"t_labF_{cid}", "prompt": prompt(cid),
                  "answer_regex": name_regex(nm), "abstain_regex": ABSTAIN})

assert len({t["id"] for t in tasks}) == 200
header = ("# ChEMBL label collision -- FULL deterministic window (CHEMBL4096=TP53,\n"
          "# ORDER BY ?chemblId LIMIT 200): ALL 124 id-only (answer NONE) + 76 named\n"
          "# (answer the name). Path A: use the whole window for power. Naturalistic\n"
          "# rate is 98.4% id-only (35,910/36,494); this balanced-ish 124:76 is the\n"
          "# deterministic top-200, disclosed as such. Control name regexes are\n"
          "# first-draft -- byte-audit against real answers.\n\n")
open("tasks.chembl_label_full.yaml", "w").write(
    header + yaml.safe_dump({"tasks": tasks}, sort_keys=False, allow_unicode=True, width=10**9))
print(f"wrote tasks.chembl_label_full.yaml: {len(ID_ONLY)} id-only + {len(NAMED)} named = {len(tasks)}")
